import{_ as i,o as t,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-11-12 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-11-12 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-11-12T00:00:00.000Z","updated":"2019-11-18T00:00:00.000Z","tags":["Ceph","Distributed Storage","Crimson","POSIX Stack","Native Stack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-12_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-11-12_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-11-12_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function r(n,l,s,_,p,S){return t(),e("div",null,[...l[0]||(l[0]=[a("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月X日</p><p><strong>会议地点</strong>： San Francisco</p><p><strong>参会人员</strong>：</p><ul><li>Alan（以色列，Ra&#39;anana办公室）</li><li>Roland</li><li>Ronnie</li><li>Peter</li><li>其他成员</li></ul><p><strong>会议主题</strong>：</p><ul><li>Ceph存储系统设计讨论</li><li>Alligator文件系统设计</li><li>Crimson性能测试</li><li>Native Stack的使用</li></ul><p><strong>会议内容</strong>：</p><p><strong>1. Alligator文件系统设计</strong></p><ul><li>讨论了是否需要文件系统以及使用Alligator的原因。</li><li>结论：由于传统文件系统无法满足Ceph的需求，Alligator将直接在块设备上运行，不使用文件系统。</li><li>关键词：Alligator, 文件系统, 块设备</li></ul><p><strong>2. Crimson性能测试</strong></p><ul><li>讨论了Crimson在POSIX和Native Stack上的性能测试结果。</li><li>结论：Native Stack在性能上具有优势，但存在一些稳定性问题。</li><li>关键词：Crimson, POSIX, Native Stack</li></ul><p><strong>3. Native Stack的使用</strong></p><ul><li>讨论了Native Stack的局限性以及是否使用的问题。</li><li>结论：目前不考虑使用Native Stack，而是专注于POSIX Stack。</li><li>关键词：Native Stack, POSIX Stack</li></ul><p><strong>4. SP Decay</strong></p><ul><li>讨论了SP Decay的实现和测试。</li><li>结论：SP Decay的实现需要优先级，但测试工作可以继续进行。</li><li>关键词：SP Decay</li></ul><p><strong>5. 其他</strong></p><ul><li>Alan介绍了自己的背景和工作。</li><li>讨论了Ceph社区和Surveillance Cluster。</li><li>讨论了Crimson和Native Stack的兼容性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>继续进行SP Decay的测试工作。</li><li>完成Alligator文件系统的设计。</li><li>优化Crimson的性能。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中涉及的技术细节较多，建议参会人员仔细阅读会议记录。</li><li>会议中提到的关键词需要进一步了解其含义。</li></ul><p><strong>改进点</strong>：</p><ul><li>在总结中增加了会议主题和参会人员信息。</li><li>梳理了会议中讨论的关键议题，并详细说明了每个议题的讨论内容和结论。</li><li>强调了会议中提到的后续行动计划。</li><li>在备注中提醒参会人员仔细阅读会议记录以了解技术细节。</li></ul>",24)])])}const u=i(o,[["render",r]]);export{c as __pageData,u as default};
